mapper.select:
SELECT TRANSFERYEAR, RC_RFILE_NO, RC_RITEM_NO, MNGNO, DETNO, DETCONNNO, PRODYEAR, ORG_FILE_PATH, SAVE_FILE_NAME FROM CN_ELEC_DOC WHERE TRANSFERYEAR = #{transferYear} AND SAVE_FILE_NAME IS NOT NULL AND NOT EXISTS ( SELECT 1 FROM EXTRACT_ELEC_DOC E WHERE E.RC_RFILE_NO = CN_ELEC_DOC.RC_RFILE_NO AND E.RC_RITEM_NO = CN_ELEC_DOC.RC_RITEM_NO AND E.FILE_NAME = CN_ELEC_DOC.SAVE_FILE_NAME
AND E.EXTRACT_STATUS = 'PASS'
AND E.EXTRACT_STATUS IN ('PASS', 'FAIL')
) ORDER BY RC_RFILE_NO, RC_RITEM_NO, SAVE_FILE_NAME LIMIT #{limit} OFFSET #{offset}
